/**
 * Real browser ZIP extraction, CRC validation and output preparation timings.
 * Generated bytes stay in memory; no third-party endpoint is contacted.
 *
 * PW_TOOLS=/path/to/qa node scripts/archive-benchmark.mjs
 * ARCHIVE_SOURCE_REF=02b078d can measure the historical ZIP source unchanged.
 * Set QA_OUTPUT to retain the JSON outside the default ignored QA directory.
 */
import assert from 'node:assert/strict'
import { build } from 'esbuild'
import { createRequire } from 'node:module'
import { createServer } from 'node:http'
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import path from 'node:path'

const root = process.cwd()
const qa = createRequire(path.join(process.env.PW_TOOLS || path.join(process.env.HOME, 'pwtools'), 'qa.cjs'))
const { chromium } = qa('playwright-core')
const sourceRef = process.env.ARCHIVE_SOURCE_REF
const source = sourceRef
  ? execFileSync('git', ['show', `${sourceRef}:lib/engines/zip.ts`], { encoding: 'utf8' })
  : readFileSync(path.join(root, 'lib/engines/zip.ts'), 'utf8')
const bundle = await build({
  stdin: { contents: "export { extractZip } from './lib/engines/zip'; export { zipSync } from 'fflate'", resolveDir: root },
  bundle: true, write: false, format: 'esm', platform: 'browser',
  plugins: [{ name: 'recorded-archive-source', setup(builder) {
    builder.onLoad({ filter: /lib\/engines\/zip\.ts$/ }, () => ({ contents: source, loader: 'ts' }))
  } }],
})
const server = createServer((request, response) => {
  response.setHeader('Cache-Control', 'no-store')
  if (request.url === '/engine.js') {
    response.setHeader('Content-Type', 'text/javascript')
    response.end(bundle.outputFiles[0].text)
  } else {
    response.setHeader('Content-Type', 'text/html')
    response.end('<script type="module">import*as engine from"/engine.js";window.engine=engine</script>')
  }
})
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve))
let browser
try {
  browser = await chromium.launch({ executablePath: process.env.CHROME_PATH || '/usr/bin/google-chrome', headless: true, args: ['--no-sandbox'] })
  const page = await browser.newPage()
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  page.on('request', request => assert(new URL(request.url()).hostname === '127.0.0.1', 'Benchmark must stay local'))
  await page.goto(`http://127.0.0.1:${server.address().port}`)
  await page.waitForFunction(() => window.engine)
  const results = await page.evaluate(async () => {
    const { extractZip, zipSync } = window.engine
    const hash = async bytes => Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)), byte => byte.toString(16).padStart(2, '0')).join('')
    const results = []
    for (const count of [1, 50, 500]) {
      const input = Object.fromEntries(Array.from({ length: count }, (_, index) => [
        `folder/entry-${String(index).padStart(3, '0')}.txt`,
        new TextEncoder().encode(`Deterministic original file ${index}: integrity preserved.`),
      ]))
      // Fixed ZIP timestamp makes the dataset byte-identical between executions.
      const entries = Object.fromEntries(Object.entries(input).map(([name, bytes]) => [name, [bytes, { mtime: new Date('2026-01-01T00:00:00Z') }]]))
      const bytes = zipSync(entries, { level: 0 })
      const inputSha256 = await hash(bytes)
      const file = new File([bytes], 'benchmark.zip', { type: 'application/zip' })
      for (let repeat = 0; repeat < 3; repeat++) {
        const started = performance.now()
        const output = await extractZip(file)
        const elapsedMs = performance.now() - started
        if (output.length !== count) throw Error('Entry count mismatch')
        for (const entry of output) {
          const actual = new Uint8Array(await entry.blob.arrayBuffer())
          const expected = input[entry.path]
          if (!expected || actual.length !== expected.length || actual.some((byte, index) => byte !== expected[index])) throw Error('Extracted bytes mismatch')
        }
        results.push({ count, repeat, elapsedMs, inputBytes: file.size, inputSha256, outputBytes: output.reduce((total, entry) => total + entry.size, 0), exactBytes: true })
      }
    }
    return results
  })
  assert.deepEqual(errors, [], 'No browser errors')
  const report = {
    measuredAt: new Date().toISOString(), browser: await browser.version(), platform: process.platform,
    sourceRef: sourceRef || 'working-tree', sourceSha256: createHash('sha256').update(source).digest('hex'),
    method: 'Real bundled source in Chromium. Three same-profile repetitions per generated stored ZIP. Timings include extraction, CRC validation and output Blob preparation, excluding fixture generation and subsequent byte comparison; not full UI or page load times.',
    results,
    medians: [1, 50, 500].map(count => ({ count, elapsedMs: results.filter(row => row.count === count).map(row => row.elapsedMs).sort((left, right) => left - right)[1] })),
    browserErrors: errors,
  }
  const directory = path.resolve(process.env.QA_OUTPUT || '.qa-results/archive-benchmark')
  mkdirSync(directory, { recursive: true })
  writeFileSync(path.join(directory, 'result.json'), JSON.stringify(report, null, 2) + '\n')
  console.log(JSON.stringify(report, null, 2))
} finally {
  await browser?.close()
  await new Promise(resolve => server.close(resolve))
}
